insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 20, 'Então Hamor e Siquém seu filho vieram à porta de sua cidade, e falaram aos homens de sua cidade, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 21, 'Estes homens são pacíficos conosco, e habitarão nesta terra, e comercializarão nela; pois eis que a terra é bastante ampla para eles; nós tomaremos suas filhas por mulheres, e lhes daremos as nossas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 22, 'Mas com esta condição nos estes homens consentirão em habitar conosco, para que sejamos um povo: se se circuncidar em nós todo homem, assim como eles são circuncidados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 23, 'Seus gados, e sua riqueza e todos seus animais, serão nossas; somente concordemos com eles, e habitarão conosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 24, 'E obedeceram a Hamor e a Siquém seu filho todos os que saíam pela porta da cidade, e circuncidaram a todo homem, dentre os que saíam pela porta de sua cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 25, 'E sucedeu que ao terceiro dia, quando sentiam eles a maior dor, os dois filhos de Jacó, Simeão e Levi, irmãos de Diná, tomaram cada um sua espada, e vieram contra a cidade animosamente, e mataram a todo homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 26, 'E a Hamor e a seu filho Siquém mataram a fio de espada; e tomaram a Diná de casa de Siquém, e saíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 27, 'E os filhos de Jacó vieram aos mortos e saquearam a cidade; porquanto haviam violado à sua irmã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 28, 'Tomaram suas ovelhas e vacas e seus asnos, e o que havia na cidade e no campo,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 29, 'E todos os seus pertences; se levaram cativos a todos as suas crianças e suas mulheres, e roubaram tudo o que havia nas casas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 30, 'Então disse Jacó a Simeão e a Levi: Vós me perturbastes em fazer-me detestável aos moradores desta terra, os cananeus e os ferezeus; e tendo eu poucos homens, se juntarão contra mim, e me ferirão, e serei destruído eu e minha casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 34, 31, 'E eles responderam Havia ele de tratar à nossa irmã como à uma prostituta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 1, 'E disse Deus a Jacó: Levanta-te, sobe a Betel, e fica ali; e faze ali um altar ao Deus que te apareceu quando fugias de teu irmão Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 2, 'Então Jacó disse à sua família e a todos os que com ele estavam: Tirai os deuses alheios que há entre vós, e limpai-vos, e mudai vossas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 3, 'E levantemo-nos, e subamos a Betel; e farei ali altar ao Deus que me respondeu no dia de minha angústia, e foi comigo no caminho que andei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 4, 'Assim deram a Jacó todos os deuses alheios que havia em poder deles, e os brincos que estavam em suas orelhas; e Jacó os escondeu debaixo de um carvalho, que estava junto a Siquém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 5, 'E partiram-se, e o terror de Deus foi sobre as cidades que havia em seus arredores, e não seguiram atrás dos filhos de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 6, 'E chegou Jacó a Luz, que está em terra de Canaã, (esta é Betel) ele e todo o povo que com ele estava;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 7, 'E edificou ali um altar, e chamou o lugar El-Betel, porque ali lhe havia aparecido Deus, quando fugia de seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 8, 'Então morreu Débora, ama de Rebeca, e foi sepultada às raízes de Betel, debaixo de um carvalho: e chamou-se seu nome Alom-Bacute.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 9, 'E apareceu-se outra vez Deus a Jacó, quando se havia voltado de Padã-Arã, e abençoou-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 10, 'E disse-lhe Deus: Teu nome é Jacó; não se chamará mais teu nome Jacó, mas sim Israel será teu nome: e chamou seu nome Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 11, 'E disse-lhe Deus: Eu sou o Deus Todo-Poderoso: cresce e multiplica-te; uma nação e conjunto de nações procederá de ti, e reis sairão de teus lombos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 12, 'E a terra que eu dei a Abraão e a Isaque, a darei a ti: e à tua descendência depois de ti darei a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 13, 'E foi-se dele Deus, do lugar onde com ele havia falado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 14, 'E Jacó erigiu uma coluna no lugar onde havia falado com ele, uma coluna de pedra, e derramou sobre ela libação, e deitou sobre ela azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 15, 'E chamou Jacó o nome daquele lugar onde Deus havia falado com ele, Betel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 16, 'E partiram de Betel, e havia ainda como alguma distância para chegar a Efrata, quando deu à luz Raquel, e houve trabalho em seu parto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 17, 'E aconteceu, que quando havia trabalho em seu parto, disse-lhe a parteira: Não temas, que também terás este filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 18, 'E aconteceu que ao sair dela a alma, (pois morreu) chamou seu nome Benoni; mas seu pai o chamou Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 19, 'Assim morreu Raquel, e foi sepultada no caminho de Efrata, a qual é Belém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 20, 'E pôs Jacó uma coluna sobre sua sepultura: esta é a coluna da sepultura de Raquel até hoje.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 21, 'E partiu Israel, e estendeu sua tenda da outra parte de Migdal-Eder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 22, 'E aconteceu, morando Israel naquela terra, que foi Rúben e dormiu com Bila a concubina de seu pai; o qual chegou a entender Israel. Agora bem, os filhos de Israel foram doze:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 23, 'Os filhos de Lia: Rúben o primogênito de Jacó, e Simeão, e Levi, e Judá, e Issacar, e Zebulom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 24, 'Os filhos de Raquel: José, e Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 25, 'E os filhos de Bila, serva de Raquel: Dã, e Naftali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 26, 'E os filhos de Zilpa, serva de Lia: Gade, e Aser. Estes foram os filhos de Jacó, que lhe nasceram em Padã-Arã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 27, 'E veio Jacó a Isaque seu pai a Manre, à cidade de Arba, que é Hebrom, onde habitaram Abraão e Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 28, 'E foram os dias de Isaque cento e oitenta anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 35, 29, 'E expirou Isaque, e morreu, e foi recolhido a seus povos, velho e farto de dias; e sepultaram-no Esaú e Jacó seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 1, 'E estas são as gerações de Esaú, o qual é Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 2, 'Esaú tomou suas mulheres das filhas de Canaã: a Ada, filha de Elom heteu, e a Oolibama, filha de Aná, filha de Zibeão os heveus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 3, 'E a Basemate, filha de Ismael, irmã de Nebaiote.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 4, 'E Ada deu à luz de Esaú a Elifaz; e Basemate deu à luz a Reuel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 5, 'E Oolibama deu à luz a Jeús, e a Jalão, e a Corá: estes são os filhos de Esaú, que lhe nasceram na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 6, 'E Esaú tomou suas mulheres, e seus filhos, e suas filhas, e todas as pessoas de sua casa, e seus gados, e todos seus animais, e todos os seus pertences que havia adquirido na terra de Canaã, e foi-se a outra terra de diante de Jacó seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 7, 'Porque a riqueza deles era grande, e não podiam habitar juntos, nem a terra de sua peregrinação os podia sustentar por causa de seus gados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 8, 'E Esaú habitou no monte de Seir: Esaú é Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 9, 'Estas são as linhagens de Esaú, pai de Edom, no monte de Seir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 10, 'Estes são os nomes dos filhos de Esaú: Elifaz, filho de Ada, mulher de Esaú; Reuel, filho de Basemate, mulher de Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 11, 'E os filhos de Elifaz foram Temã, Omar, Zefô, Gatã, e Quenaz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 12, 'E Timna foi concubina de Elifaz, filho de Esaú, a qual lhe deu à luz a Amaleque: estes são os filhos de Ada, mulher de Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 13, 'E os filhos de Reuel foram Naate, Zerá, Samá, e Mizá: estes são os filhos de Basemate, mulher de Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 14, 'Estes foram os filhos de Oolibama, mulher de Esaú, filha de Aná, que foi filha de Zibeão: ela deu à luz de Esaú a Jeús, Jalão, e Corá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 15, 'Estes são os duques dos filhos de Esaú. Filhos de Elifaz, primogênito de Esaú: o duque Temã, o duque Omar, o duque Zefô, o duque Quenaz,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 16, 'O duque Corá, o duque Gatã, e o duque Amaleque: estes são os duques de Elifaz na terra de Edom; estes foram os filhos de Ada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 17, 'E estes são os filhos de Reuel, filho de Esaú: o duque Naate, o duque Zerá, o duque Samá, e o duque Mizá: estes são os duques da linha de Reuel na terra de Edom; estes filhos vêm de Basemate, mulher de Esaú.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 18, 'E estes são os filhos de Oolibama, mulher de Esaú: o duque Jeús, o duque Jalão, e o duque Corá: estes foram os duques que saíram de Oolibama, mulher de Esaú, filha de Aná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 19, 'Estes, pois, são os filhos de Esaú, e seus duques: ele é Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 20, 'E estes são os filhos de Seir horeu, moradores daquela terra: Lotã, Sobal, Zibeão, Aná,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 21, 'Disom, Eser, e Disã: estes são os duques dos horeus, filhos de Seir na terra de Edom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 22, 'Os filhos de Lotã foram Hori e Hemã; e Timna foi irmã de Lotã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 23, 'E os filhos de Sobal foram Alvã, Manaate, Ebal, Sefô, e Onã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 24, 'E os filhos de Zibeão foram Aiá, e Aná. Este Aná é o que descobriu as fontes termais no deserto, quando apascentava os asnos de Zibeão seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 25, 'Os filhos de Aná foram Disom, e Oolibama, filha de Aná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 26, 'E estes foram os filhos de Disom: Hendã, Esbã, Itrã, e Querã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 27, 'E estes foram os filhos de Eser: Bilã, Zaavã, e Acã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 28, 'Estes foram os filhos de Disã: Uz, e Harã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 29, 'E estes foram os duques dos horeus: o duque Lotã, o duque Sobal, o duque Zibeão, o duque Aná.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 30, 'O duque Disom, o duque Eser, o duque Disã: estes foram os duques dos horeus: por seus ducados na terra de Seir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 31, 'E os reis que reinaram na terra de Edom, antes que reinasse rei sobre os filhos de Israel, foram estes:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 32, 'Belá, filho de Beor, reinou em Edom: e o nome de sua cidade foi Dinabá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 33, 'E morreu Belá, e reinou em seu lugar Jobabe, filho de Zerá, de Bozra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 34, 'E morreu Jobabe, e em seu lugar reinou Husão, da terra de Temã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 35, 'E morreu Husão, e reinou em seu lugar Hadade, filho de Bedade, o que feriu a Midiã no campo de Moabe: e o nome de sua cidade foi Avite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 36, 'E morreu Hadade, e em seu lugar reinou Samlá, de Masreca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 37, 'E morreu Samlá, e reinou em seu lugar Saul, de Reobote do rio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 38, 'E morreu Saul, e em seu lugar reinou Baal-Hanã, filho de Acbor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 39, 'E morreu Baal-Hanã, filho de Acbor, e reinou Hadar em seu lugar: e o nome de sua cidade foi Paú; e o nome de sua mulher Meetabel, filha de Matrede, filha de Mezaabe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 40, 'Estes, pois, são os nomes dos duques de Esaú por suas linhagens, por seus lugares, e seus nomes: o duque Timna, o duque Alva, o duque Jetete,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 41, 'O duque Oolibama, o duque Elá, o duque Pinom,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 42, 'O duque Quenaz, o duque Temã, o duque Mibzar,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 36, 43, 'O duque Magdiel, e o duque Hirão. Estes foram os duques de Edom por suas habitações na terra de sua possessão. Edom é o mesmo Esaú, pai dos edomitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 1, 'E habitou Jacó na terra onde peregrinou seu pai, na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 2, 'Estas foram as gerações de Jacó. José, sendo de idade de dezessete anos apascentava as ovelhas com seus irmãos; e o jovem estava com os filhos de Bila, e com os filhos de Zilpa, mulheres de seu pai: e contava José a seu pai as más notícias acerca deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 3, 'E amava Israel a José mais que a todos os seus filhos, porque lhe havia tido em sua velhice: e lhe fez uma roupa de diversas cores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 4, 'E vendo seus irmãos que seu pai o amava mais que a todos os seus irmãos, odiavam-lhe, e não lhe podiam falar pacificamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 5, 'E sonhou José um sonho e contou-o a seus irmãos; e eles vieram a odiar-lhe mais ainda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 6, 'E ele lhes disse: Ouvi agora este sonho que sonhei:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 7, 'Eis que atávamos feixes no meio do campo, e eis que meu feixe se levantava, e estava em pé, e que vossos feixes estavam ao redor, e se inclinavam ao meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 8, 'E responderam-lhe seus irmãos: Reinarás tu sobre nós, ou serás tu senhor sobre nós? E o odiaram ainda mais por causa de seus sonhos e de suas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 9, 'E sonhou ainda outro sonho, e contou-o a seus irmãos, dizendo: Eis que sonhei outro sonho, e eis que o sol e a lua e onze estrelas se inclinavam a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 10, 'E contou-o a seu pai e a seus irmãos: e seu pai lhe repreendeu, e disse-lhe: Que sonho é este que sonhaste? Viremos eu e tua mãe, e teus irmãos, a nos inclinarmos a ti em terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 11, 'E seus irmãos lhe tinham inveja, mas seu pai guardava isso em mente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 12, 'E foram seus irmãos a apascentar as ovelhas de seu pai em Siquém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 13, 'E disse Israel a José: Teus irmãos apascentam as ovelhas em Siquém: vem, e te enviarei a eles. E ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 14, 'E ele lhe disse: Vai agora, olha como estão teus irmãos e como estão as ovelhas, e traze-me a resposta. E enviou-o do vale de Hebrom, e chegou a Siquém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 15, 'E achou-o um homem, andando ele perdido pelo campo, e perguntou-lhe aquele homem, dizendo: Que buscas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 16, 'E ele respondeu: Busco a meus irmãos: rogo-te que me mostres onde apascentam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 17, 'E aquele homem respondeu: Já se foram daqui; eu lhes ouvi dizer: Vamos a Dotã. Então José foi atrás de seus irmãos, e achou-os em Dotã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 18, 'E quando eles o viram de longe, antes que perto deles chegasse, tramaram contra ele para matar-lhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 19, 'E disseram um ao outro: Eis que vem o sonhador;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 20, 'Agora, pois, vinde, e o matemos e o lancemos em uma cisterna, e diremos: Alguma fera selvagem o devorou: e veremos que serão seus sonhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 21, 'E quando Rúben ouviu isto, livrou-o de suas mãos e disse: Não o matemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 22, 'E disse-lhes Rúben: Não derrameis sangue; lançai-o nesta cisterna que está no deserto, e não ponhais mão nele; para livrá-lo assim de suas mãos, para fazê-lo virar a seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 23, 'E sucedeu que, quando chegou José a seus irmãos, eles fizeram desnudar a José sua roupa, a roupa de cores que tinha sobre si;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 24, 'E tomaram-no, e lançaram-lhe na cisterna; mas a cisterna estava vazia, não havia nela água.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 25, 'E sentaram-se a comer pão: e levantando os olhos olharam, e eis uma companhia de ismaelitas que vinha de Gileade, e seus camelos traziam aromas e bálsamo e mirra, e iam a levá-lo ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 26, 'Então Judá disse a seus irmãos: Que proveito há em que matemos a nosso irmão e encubramos sua morte?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 27, 'Vinde, e o vendamos aos ismaelitas, e não seja nossa mão sobre ele; que nosso irmão é nossa carne. E seus irmãos concordaram com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 28, 'E quando passavam os midianitas mercadores, tiraram eles a José da cisterna, e trouxeram-lhe acima, e o venderam aos ismaelitas por vinte peças de prata. E levaram a José ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 29, 'E Rúben voltou à cisterna, e não achou a José dentro, e rasgou suas roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 30, 'E voltou a seus irmãos e disse: O jovem não aparece; e eu, aonde irei eu?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 31, 'Então eles tomaram a roupa de José, e degolaram um cabrito das cabras, e tingiram a roupa com o sangue;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 32, 'E enviaram a roupa de cores e trouxeram-na a seu pai, e disseram: Achamos isto, reconhece agora se é ou não a roupa de teu filho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 33, 'E ele a reconheceu, e disse: A roupa de meu filho é; alguma fera selvagem o devorou; José foi despedaçado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 34, 'Então Jacó rasgou suas roupas, e pôs saco sobre seus lombos, e fez luto por seu filho muitos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 35, 'E levantaram-se todos os seus filhos e todas as suas filhas para consolá-lo; mas ele não quis receber consolação, e disse: Porque eu tenho de descer ao meu filho com luto ao Xeol. E seu pai chorou por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 37, 36, 'E os midianitas o venderam no Egito a Potifar, oficial de Faraó, capitão dos da guarda.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 1, 'E aconteceu naquele tempo, que Judá desceu da presença de seus irmãos, e foi-se a um homem adulamita, que se chamava Hira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 2, 'E viu ali Judá a filha de um homem cananeu, o qual se chamava Sua; e tomou-a, e se deitou com ela:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 3, 'A qual concebeu, e deu à luz um filho; e chamou seu nome Er.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 4, 'E concebeu outra vez, e deu à luz um filho, e chamou seu nome Onã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 5, 'E voltou a conceber, e deu à luz um filho, e chamou seu nome Selá. E estava em Quezibe quando o deu à luz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 6, 'E Judá tomou mulher para seu primogênito Er, a qual se chamava Tamar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 7, 'E Er, o primogênito de Judá, foi mau aos olhos do SENHOR, e tirou-lhe o SENHOR a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 8, 'Então Judá disse a Onã: Deita-te com mulher de teu irmão, e casa-te com ela, e suscita descendência a teu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 9, 'E sabendo Onã que a descendência não havia de ser sua, sucedia que quando se deitava com mulher de seu irmão derramava em terra, para não dar descendência a seu irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 10, 'E desagradou aos olhos do SENHOR o que fazia, e também tirou a ele a vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 11, 'E Judá disse a Tamar sua nora: Fica-te viúva em casa de teu pai, até que cresça Selá meu filho; porque disse: Para que não aconteça que morra ele também como seus irmãos. E foi-se Tamar, e ficou em casa de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 12, 'E passaram muitos dias, e morreu a filha de Sua, mulher de Judá; e Judá se consolou, e subia aos tosquiadores de suas ovelhas a Timna, ele e seu amigo Hira o adulamita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 13, 'E foi dado aviso a Tamar, dizendo: Eis que teu sogro sobe a Timna a tosquiar suas ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 14, 'Então tirou ela de sobre si as roupas de sua viuvez, e cobriu-se com um véu, e envolveu-se, e se pôs à porta das águas que estão junto ao caminho de Timna; porque via que havia crescido Selá, e ela não era dada a ele por mulher.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 15, 'E viu-a Judá, e teve-a por prostituta, porque havia ela coberto seu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 16, 'E desviou-se do caminho até ela, e disse-lhe: Eia, pois, agora deitarei contigo; porque não sabia que era sua nora; e ela disse: Que me darás, se deitares comigo?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 17, 'Ele respondeu: Eu te enviarei do gado um cabrito das cabras. E ela disse: Terás de me dar penhor até que o envies.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 18, 'Então ele disse: Que penhor te darei? Ela respondeu: Teu anel, e teu manto, e teu bordão que tens em tua mão. E ele lhe deu, e se deitou com ela, a qual concebeu dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 19, 'E levantou-se, e foi-se: e tirou o véu de sobre si, e vestiu-se das roupas de sua viuvez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 20, 'E Judá enviou o cabrito das cabras por meio de seu amigo o adulamita, para que tomasse o penhor da mão da mulher; mas não a achou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 21, 'E perguntou aos homens daquele lugar, dizendo: Onde está a prostituta das águas junto ao caminho? E eles lhe disseram: Não esteve aqui prostituta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 22, 'Então ele se voltou a Judá, e disse: Não a achei; e também os homens do lugar disseram: Aqui não esteve prostituta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 23, 'E Judá disse: Tome ela dessas coisas para si, para que não sejamos menosprezados: eis que eu enviei este cabrito, e tu não a achaste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 24, 'E aconteceu que ao fim de uns três meses foi dado aviso a Judá, dizendo: Tamar tua nora cometeu imoralidade sexual, e além disso está grávida das promiscuidades. E Judá disse: Tirai-a, e seja queimada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 25, 'E ela quando a tiravam, enviou a dizer a seu sogro: Do homem a quem pertence estas coisas, estou grávida: e disse mais: Olha agora a quem pertence estas coisas, o anel, e o manto, e o bordão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 26, 'Então Judá os reconheceu, e disse: Mais justa é que eu, porquanto não a dei a Selá meu filho. E nunca mais a conheceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 27, 'E aconteceu que ao tempo de dar à luz, eis que havia dois em seu ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 28, 'E sucedeu, quando dava à luz, que tirou a mão um, e a parteira tomou e amarrou à sua mão um fio de escarlate, dizendo: Este saiu primeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 29, 'Porém foi que voltando ele a recolher a mão, eis que seu irmão saiu; e ela disse: Como fizeste sobre ti rompimento? E chamou seu nome Perez.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 38, 30, 'E depois saiu seu irmão, o que tinha em sua mão o fio de escarlate, e chamou seu nome Zerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 1, 'E levado José ao Egito, comprou-o Potifar, oficial de Faraó, capitão dos da guarda, homem egípcio, da mão dos ismaelitas que o haviam levado ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 2, 'Mas o SENHOR foi com José, e foi homem próspero: e estava na casa de seu senhor o egípcio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 3, 'E viu seu senhor que o SENHOR era com ele, e que tudo o que ele fazia, o SENHOR o fazia prosperar em sua mão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 4, 'Assim achou José favor em seus olhos, e servia-lhe; e ele lhe fez mordomo de sua casa, e entregou em seu poder tudo o que tinha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 5, 'E aconteceu que, desde quando lhe deu o encargo de sua casa, e de tudo o que tinha, o SENHOR abençoou a casa do egípcio por causa de José; e a bênção do SENHOR foi sobre tudo o que tinha, tanto em casa como no campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 6, 'E deixou tudo o que tinha em mão de José; nem com ele sabia de nada mais que do pão que comia. E era José de belo semblante e bela presença.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 7, 'E aconteceu depois disto, que a mulher de seu senhor pôs seus olhos em José, e disse: Dorme comigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 8, 'E ele não quis, e disse à mulher de seu senhor: Eis que meu senhor não sabe comigo o que há em casa, e pôs em minha mão tudo o que tem:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 9, 'Não há outro maior que eu nesta casa, e nenhuma coisa me há reservado a não ser a ti, porquanto tu és sua mulher; como, pois, faria eu este grande mal e pecaria contra Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 10, 'E foi que falando ela a José cada dia, e não escutando-a ele para deitar-se ao lado dela, para estar com ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 11, 'Aconteceu que entrou ele um dia em casa para fazer seu ofício, e não havia ninguém dos da casa ali em casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 12, 'E pegou-o ela por sua roupa, dizendo: Dorme comigo. Então ele deixou sua roupa nas mãos dela, e fugiu, e saiu-se fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 13, 'E aconteceu que quando viu ela que lhe havia deixado sua roupa em suas mãos, e havia fugido fora,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 14, 'Chamou aos de casa, e falou-lhes dizendo: Olhai que ele nos trouxe um hebreu, para que fizesse zombaria de nós: veio ele a mim para dormir comigo, e eu dei grandes vozes;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 15, 'E vendo que eu erguia a voz e gritava, deixou junto a mim sua roupa, e fugiu, e saiu-se fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 16, 'E ela pôs junto a si a roupa dele, até que veio seu senhor à sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 17, 'Então lhe falou ela semelhantes palavras, dizendo: O servo hebreu que nos trouxeste, veio a mim para desonrar-me;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 18, 'E quando eu levantei minha voz e gritei, ele deixou sua roupa junto a mim, e fugiu fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 19, 'E sucedeu que quando ouviu seu senhor as palavras que sua mulher lhe falara, dizendo: Assim me tratou teu servo; acendeu-se seu furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 20, 'E tomou seu senhor a José, e pôs-lhe na casa do cárcere, onde estavam os presos do rei, e esteve ali na casa do cárcere.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 21, 'Mas o SENHOR foi com José, e estendeu a ele sua misericórdia, e deu-lhe favor aos olhos do chefe da casa do cárcere.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 22, 'E o chefe da casa do cárcere entregou em mão de José todos os presos que havia naquela prisão; tudo o que faziam ali, ele o fazia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 39, 23, 'Não via o chefe do cárcere coisa alguma que em sua mão estava; porque o SENHOR era com ele, e o que ele fazia, o SENHOR o fazia prosperar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 1, 'E aconteceu depois destas coisas, que o copeiro do rei do Egito e o padeiro transgrediram contra seu senhor o rei do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 2, 'E irou-se Faraó contra seus dois eunucos, contra o principal dos copeiros, e contra o principal dos padeiros:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 3, 'E os pôs em prisão na casa do capitão dos da guarda, na casa do cárcere onde José estava preso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 4, 'E o capitão dos da guarda deu responsabilidade deles a José, e ele lhes servia: e estiveram dias na prisão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 5, 'E ambos, o copeiro e o padeiro do rei do Egito, que estavam detidos na prisão, viram um sonho, cada um seu sonho em uma mesma noite, cada um conforme a declaração de seu sonho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 6, 'E veio a eles José pela manhã, e olhou-os, e eis que estavam tristes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 7, 'E ele perguntou àqueles oficiais de Faraó, que estavam com ele na prisão da casa de seu senhor, dizendo: Por que parecem hoje mal vossos semblantes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 8, 'E eles lhe disseram: Tivemos um sonho, e não há quem o declare. Então lhes disse José: Não são de Deus as interpretações? Contai-o a mim agora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 9, 'Então o chefe dos copeiros contou seu sonho a José, e disse-lhe: Eu sonhava que via uma vide diante de mim,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 10, 'E na vide três sarmentos; e ela como que brotava, e surgia sua flor, vindo a amadurecer seus cachos de uvas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 11, 'E que o copo de Faraó estava em minha mão, e tomava eu as uvas, e as espremia no copo de Faraó, e dava eu o copo em mão de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 12, 'E disse-lhe José: Esta é sua declaração: Os três sarmentos são três dias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 13, 'Ao fim de três dias Faraó te fará levantar a cabeça, e te restituirá a teu posto: e darás o copo a Faraó em sua mão, como costumavas quando eras seu copeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 14, 'Lembra-te, pois, de mim para contigo quando tiveres esse bem, e rogo-te que uses comigo de misericórdia, e faças menção de mim a Faraó, e me tires desta prisão:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 15, 'Porque furtado fui da terra dos hebreus; e tampouco fiz aqui para que me houvessem de pôr no cárcere.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 16, 'E vendo o chefe dos padeiros que havia interpretado para o bem, disse a José: Também eu sonhava que via três cestos brancos sobre minha cabeça;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 17, 'E no cesto mais alto havia de todos os alimentos de Faraó, obra de padeiro; e que as aves as comiam do cesto de sobre minha cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 18, 'Então respondeu José, e disse: Esta é sua declaração: Os três cestos três dias são;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 19, 'Ao fim de três dias tirará Faraó tua cabeça de sobre ti, e te fará enforcar na forca, e as aves comerão tua carne de sobre ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 20, 'E foi o terceiro dia o dia do aniversário de Faraó, e fez banquete a todos os seus servos: e levantou a cabeça do chefe dos copeiros, e a cabeça do chefe dos padeiros, entre seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 21, 'E fez voltar a seu ofício ao chefe dos copeiros; e deu ele o copo em mão de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 22, 'Mas fez enforcar ao principal dos padeiros, como lhe havia declarado José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 40, 23, 'E o chefe dos copeiros não se lembrou de José, ao invés disso lhe esqueceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 1, 'E aconteceu que passados dois anos teve Faraó um sonho: Parecia-lhe que estava junto ao rio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 2, 'E que do rio subiam sete vacas, belas à vista, e muito gordas, e pastavam entre os juncos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 3, 'E que outras sete vacas subiam depois delas do rio, de feia aparência, e magras de carne, e pararam perto das vacas belas à beira do rio;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 4, 'E que as vacas de feia aparência e magras de carne devoravam as sete vacas belas e muito gordas. E despertou Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 5, 'Dormiu de novo, e sonhou a segunda vez: Que sete espigas cheias e belas subiam de uma só haste:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 6, 'E que outras sete espigas miúdas e abatidas do vento oriental, saíam depois delas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 7, 'E as sete espigas miúdas devoravam as sete espigas espessas e cheias. E despertou Faraó, e eis que era sonho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 8, 'E aconteceu que à manhã estava movido seu espírito; e enviou e fez chamar a todos os magos do Egito, e a todos os seus sábios: e contou-lhes Faraó seus sonhos, mas não havia quem a Faraó os interpretasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 9, 'Então o chefe dos copeiros falou a Faraó, dizendo: Lembro-me hoje de minhas faltas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 10, 'Faraó se irou contra seus servos, e a mim me lançou à prisão da casa do capitão dos da guarda, a mim e ao chefe dos padeiros:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 11, 'E eu e ele vimos um sonho uma mesma noite: cada um sonhou conforme a interpretação de seu sonho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 12, 'E estava ali conosco um jovem hebreu, servente do capitão dos da guarda; e o contamos a ele, e ele nos interpretou nossos sonhos, e interpretou a cada um conforme seu sonho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 13, 'E aconteceu que como ele nos interpretou, assim foi: a mim me fez voltar a meu posto, e fez enforcar ao outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 14, 'Então Faraó enviou e chamou a José; e fizeram-lhe sair correndo do cárcere; e ele rapou-se a barba, mudou-se de roupas, e veio a Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 15, 'E disse Faraó a José: Eu tive um sonho, e não há quem o interprete; mas ouvi dizer de ti, que ouves sonhos para os interpretar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 16, 'E respondeu José a Faraó, dizendo: Não está em mim; Deus será o que responda paz a Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 17, 'Então Faraó disse a José: Em meu sonho parecia-me que estava à beira do rio:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 18, 'E que do rio subiam sete vacas de gordas carnes e bela aparência, que pastavam entre os juncos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 19, 'E que outras sete vacas subiam depois delas, magras e de muito feio aspecto; tão abatidas, que não vi outras semelhantes em toda a terra do Egito em feiura:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 20, 'E as vacas magras e feias devoravam as sete primeiras vacas gordas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 21, 'E entravam em suas entranhas, mas não se conhecia que houvesse entrado nelas, porque sua aparência era ainda má, como de antes. E eu despertei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 22, 'Vi também sonhando, que sete espigas subiam em uma mesma haste, cheias e belas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 23, 'E que outras sete espigas miúdas, definhadas, abatidas do vento oriental, subiam depois delas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 24, 'E as espigas miúdas devoravam as sete espigas belas: e disse-o aos magos, mas não há quem o interprete a mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 25, 'Então respondeu José a Faraó: O sonho de Faraó é um mesmo: Deus mostrou a Faraó o que vai fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 26, 'As sete vacas belas são sete anos, e as espigas belas são sete anos; o sonho é um mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 27, 'Também as sete vacas magras e feias que subiam atrás elas, são sete anos; e as sete espigas miúdas e definhadas do vento oriental serão sete anos de fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 28, 'Isto é o que respondo a Faraó. O que Deus vai fazer, mostrou-o a Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 29, 'Eis que vêm sete anos de grande fartura toda a terra do Egito:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 30, 'E se levantarão depois eles sete anos de fome; e toda a fartura será esquecida na terra do Egito; e a fome consumirá a terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 31, 'E aquela abundância não mais será vista por causa da fome seguinte, a qual será gravíssima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 32, 'E o suceder o sonho a Faraó duas vezes, significa que a coisa é firme da parte de Deus, e que Deus se apressa a fazê-la.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 33, 'Portanto, providencie Faraó agora um homem prudente e sábio, e ponha-o sobre a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 34, 'Faça isto Faraó, e ponha governadores sobre esta terra, e tome a quinta parte da terra do Egito nos sete anos da fartura;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 35, 'E juntem toda a provisão destes bons anos que vêm, e acumulem o trigo sob a mão de Faraó para mantimento das cidades; e guardem-no.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 36, 'E esteja aquela provisão em depósito para esta terra, para os sete anos de fome que serão na terra do Egito; e esta terra não perecerá de fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 37, 'E o negócio pareceu bem a Faraó, e a seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 38, 'E disse Faraó a seus servos: Acharemos outro homem como este, em quem haja espírito de Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 39, 'E disse Faraó a José: Pois que Deus te fez saber tudo isto, não há entendido nem sábio como tu:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 40, 'Tu serás sobre minha casa, e pelo que disseres se governará todo o meu povo; somente no trono serei eu maior que tu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 41, 'Disse mais Faraó a José: Eis que te pus sobre toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 42, 'Então Faraó tirou seu anel de sua mão, e o pôs na mão de José, e fez-lhe vestir de roupas de linho finíssimo, e pôs um colar de ouro em seu pescoço;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 43, 'E o fez subir em seu segundo carro, e proclamaram diante dele: Dobrai os joelhos; e pôs-lhe sobre toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 44, 'E disse Faraó a José: Eu sou Faraó; e sem ti ninguém levantará sua mão nem seu pé toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 45, 'E chamou Faraó o nome de José, Zefenate-Paneia; e deu-lhe por mulher a Azenate, filha de Potífera, sacerdote de Om. E saiu José por toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 46, 'E era José de idade de trinta anos quando foi apresentado diante de Faraó, rei do Egito: e saiu José de diante de Faraó, e transitou por toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 47, 'E fez a terra naqueles sete anos de fartura a amontoados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 48, 'E ele juntou todo o mantimento dos sete anos que foram na terra do Egito, e guardou mantimento nas cidades, pondo em cada cidade o mantimento do campo de seus arredores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 49, 'E ajuntou José trigo como areia do mar, muito em extremo, até não se poder contar, porque não tinha número.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 50, 'E nasceram a José dois filhos antes que viesse o primeiro ano da fome, os quais lhe deu à luz Azenate, filha de Potífera, sacerdote de Om.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 51, 'E chamou José o nome do primogênito Manassés; porque disse: Deus me fez esquecer todo o meu sofrimento, e toda a casa de meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 52, 'E o nome do segundo chamou-o Efraim; porque disse: “Deus me fez frutífero na terra de minha aflição”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 53, 'E cumpriram-se os sete anos da fartura, que houve na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 54, 'E começaram a vir os sete anos de fome, como José havia dito; e houve fome em todos os países, mas em toda a terra do Egito havia pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 55, 'E quando se sentiu a fome toda a terra do Egito, o povo clamou a Faraó por pão. E disse Faraó a todos os egípcios: Ide a José, e fazei o que ele vos disser.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 56, 'E a fome estava por toda a extensão daquela terra. Então abriu José todo depósito de grãos onde havia, e vendia aos egípcios; porque havia crescido a fome na terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 41, 57, 'E toda a terra vinha ao Egito para comprar de José, porque por toda a terra havia aumentado a fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 1, 'E vendo Jacó que no Egito havia alimentos, disse a seus filhos: Por que estais olhando uns para os outros?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 2, 'E disse: Eis que, eu ouvi que há alimentos no Egito; descei ali, e comprai dali para nós, para que possamos viver, e não nos morramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 3, 'E desceram os dez irmãos de José a comprar trigo ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 4, 'Mas Jacó não enviou a Benjamim irmão de José com seus irmãos; porque disse: Não seja acaso que lhe aconteça algum desastre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 5, 'E vieram os filhos de Israel a comprar entre os que vinham: porque havia fome na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 6, 'E José era o senhor da terra, que vendia a todo o povo da terra: e chegaram os irmãos de José, e inclinaram-se a ele rosto por terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 7, 'E José quando viu seus irmãos, reconheceu-os; mas fez que não os conhecesse, e falou-lhes asperamente, e lhes disse: De onde viestes? Eles responderam: Da terra de Canaã, para comprar alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 8, 'José, pois, reconheceu a seus irmãos; mas eles não o reconheceram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 9, 'Então se lembrou José dos sonhos que havia tido deles, e disse-lhes: Sois espias; viestes ver a fraqueza desta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 10, 'E eles lhe responderam: Não, meu senhor; teus servos vieram comprar alimentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 11, 'Todos nós somos filhos de um homem; somos homens honestos; teus servos nunca foram espias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 12, 'E ele lhes disse: Não; viestes ver a fraqueza desta terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 13, 'E eles responderam: Teus servos somos doze irmãos, filhos de um homem na terra de Canaã; e eis que o menor está hoje com nosso pai, e outro desapareceu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 14, 'E José lhes disse: Isso é o que vos disse, afirmando que sois espias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 15, 'Nisto sereis provados: Vive Faraó que não saireis daqui, a não ser quando vosso irmão menor vier aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 16, 'Enviai um de vós, e traga a vosso irmão; e vós ficai presos, e vossas palavras serão provadas, se há verdade convosco: e se não, vive Faraó, que sois espias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 17, 'E juntou-os no cárcere por três dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 18, 'E ao terceiro dia disse-lhes José: Fazei isto, e vivei; eu temo a Deus;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 19, 'Se sois homens honestos, fique preso na casa de vosso cárcere um de vossos irmãos; e vós ide, levai o alimento para a fome de vossa casa;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 20, 'Porém haveis de trazer-me a vosso irmão mais novo, e serão comprovadas vossas palavras, e não morrereis. E eles o fizeram assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 21, 'E diziam um ao outro: Verdadeiramente pecamos contra nosso irmão, que vimos a angústia de sua alma quando nos rogava, e não o ouvimos; por isso veio sobre nós esta angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 22, 'Então Rúben lhes respondeu, dizendo: Não vos falei eu e disse: Não pequeis contra o jovem; e não escutastes? Eis que também o sangue dele é requerido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 23, 'E eles não sabiam que os entendia José, porque havia intérprete entre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 24, 'E apartou-se ele deles, e chorou: depois voltou a eles, e lhes falou, e tomou dentre eles a Simeão, e aprisionou-lhe à vista deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 25, 'E mandou José que enchessem seus sacos de trigo, e devolvessem o dinheiro de cada um deles, pondo-o em seu saco, e lhes dessem comida para o caminho; e fez-se assim com eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 26, 'E eles puseram seu trigo sobre seus asnos, e foram-se dali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 27, 'E abrindo um deles seu saco para dar de comer a seu asno no lugar de parada, viu seu dinheiro que estava na boca de seu saco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 28, 'E disse a seus irmãos: Meu dinheiro se me foi devolvido, e ainda ei-lo aqui em meu saco. Alarmou-se, então, o coração deles e, espantados, disseram um ao outro: Que é isto que Deus nos fez?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 29, 'E vindos a Jacó seu pai em terra de Canaã, contaram-lhe tudo o que lhes havia acontecido, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 30, 'Aquele homem, senhor da terra, nos falou asperamente, e nos tratou como espias da terra:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 31, 'E nós lhe dissemos: Somos homens honestos, nunca fomos espias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 32, 'Somos doze irmãos, filhos de nosso pai; um desapareceu, e o menor está hoje com nosso pai na terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 33, 'E aquele homem, senhor da terra, nos disse: Nisto conhecerei que sois homens honestos; deixai comigo um de vossos irmãos, e tomai para a fome de vossas casas, e ide,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 34, 'E trazei-me a vosso irmão o mais novo, para que eu saiba que não sois espias, mas sim homens honestos: assim vos darei a vosso irmão, e negociareis na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 35, 'E aconteceu que esvaziando eles seus sacos, eis que no saco de cada um estava o pacote de seu dinheiro: e vendo eles e seu pai os pacotes de seu dinheiro, tiveram temor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 36, 'Então seu pai Jacó lhes disse: Vós me privastes de meus filhos; José desapareceu, nem Simeão tampouco, e a Benjamim o levareis; contra mim são todas estas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 37, 'E Rúben falou a seu pai, dizendo: Podes matar meus dois filhos, se eu não o devolver a ti; entrega-o em minha mão, que eu o devolverei a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 42, 38, 'E ele disse: Não descerá meu filho convosco; que seu irmão é morto, e ele somente restou; e se lhe acontecer algum desastre no caminho por onde vades, fareis descer meus cabelos brancos com tristeza ao Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 1, 'E a fome era grande na terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 2, 'E aconteceu que quando acabaram de comer o trigo que trouxeram do Egito, disse-lhes seu pai: Voltai, e comprai para nós um pouco de alimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 3, 'E respondeu Judá, dizendo: Aquele homem nos advertiu com ânimo decidido, dizendo: Não vereis meu rosto sem vosso irmão convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 4, 'Se enviares a nosso irmão conosco, desceremos e te compraremos alimento:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 5, 'Porém se não lhe enviares, não desceremos: porque aquele homem nos disse: Não vereis meu rosto sem vosso irmão convosco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 6, 'E disse Israel: Por que me fizestes tanto mal, declarando ao homem que tínheis mais irmão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 7, 'E eles responderam: Aquele homem nos perguntou expressamente por nós, e por nossa parentela, dizendo: Vive ainda vosso pai? Tendes outro irmão? E lhe declaramos conforme estas palavras. Podíamos nós saber que havia de dizer: Fazei vir a vosso irmão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 8, 'Então Judá disse a Israel seu pai: Envia ao jovem comigo, e nos levantaremos e iremos, a fim que vivamos e não morramos nós, e tu, e nossos filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 9, 'Eu sou fiador dele; a mim me pedirás conta dele; se eu não o devolver a ti e o puser diante de ti, serei para ti o culpado todos os dias:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 10, 'Que se não nos tivéssemos detido, certo agora teríamos já voltado duas vezes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 11, 'Então Israel seu pai lhes respondeu: Pois que assim é, fazei-o; tomai do melhor da terra em vossos vasos, e levai àquele homem um presente, um pouco de bálsamo, e um pouco de mel, aromas e mirra, nozes e amêndoas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 12, 'E tomai em vossas mãos dobrado dinheiro, e levai em vossa mão o dinheiro que voltou nas bocas de vossos sacos; talvez tenha sido erro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 13, 'Tomai também a vosso irmão, e levantai-vos, e voltai àquele homem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 14, 'E o Deus Todo-Poderoso vos dê misericórdias diante daquele homem, e vos solte ao outro vosso irmão, e a este Benjamim. E se eu tiver de ser privado de meus filhos, assim seja.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 15, 'Então tomaram aqueles homens o presente, e tomaram em sua mão dobrado dinheiro, e a Benjamim; e se levantaram, e desceram ao Egito, e apresentaram-se diante de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 16, 'E viu José a Benjamim com eles, e disse ao mordomo de sua casa: Mete em casa a esses homens, e degola um animal, e prepara-o; porque estes homens comerão comigo ao meio-dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 17, 'E fez o homem como José disse; e meteu aquele homem aos homens em casa de José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 18, 'E aqueles homens tiveram temor, quando foram metidos na casa de José, e diziam: Pelo dinheiro que voltou em nossos sacos a primeira vez nos trouxeram aqui, para virem contra nós, e nos atacar, e tomar por servos a nós, e a nossos asnos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 19, 'E aproximaram-se do mordomo da casa de José, e lhe falaram à entrada da casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 20, 'E disseram: Ai, senhor meu, nós em realidade de verdade descemos ao princípio a comprar alimentos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 21, 'E aconteceu que quando viemos ao lugar de parada e abrimos nossos sacos, eis que o dinheiro de cada um estava na boca de seu saco, nosso dinheiro em seu justo peso; e o devolvemos em nossas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 22, 'Trouxemos também em nossas mãos outro dinheiro para comprar alimentos: nós não sabemos quem pôs nosso dinheiro em nossos sacos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 23, 'E ele respondeu: Paz a vós, não temais; vosso Deus e o Deus de vosso pai vos deu o tesouro em vossos sacos: vosso dinheiro veio a mim. E tirou a Simeão a eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 24, 'E aquele homem levou àqueles homens na casa de José: e deu-lhes água, e lavaram seus pés: e deu de comer a seus asnos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 25, 'E eles prepararam o presente antes que viesse José ao meio-dia, porque haviam ouvido que ali haviam de comer pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 26, 'E veio José a casa, e eles lhe trouxeram o presente que tinham em sua mão dentro de casa, e inclinaram-se a ele em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 27, 'Então ele lhes perguntou como estavam, e disse: Vosso pai, o ancião que dissestes, passa bem? Vive ainda?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 28, 'E eles responderam: Bem vai a teu servo nosso pai; ainda vive. E se inclinaram, e fizeram reverência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 29, 'E levantando ele seus olhos viu Benjamim seu irmão, filho de sua mãe, e disse: É este vosso irmão mais novo, de quem me falastes? E disse: Deus tenha misericórdia de ti, filho meu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 30, 'Então José se apressou, porque se comoveram suas entranhas por causa de seu irmão, e procurou onde chorar: e entrou-se em sua câmara, e chorou ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 31, 'E lavou seu rosto, e saiu fora, e controlou-se, e disse: Ponde pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 32, 'E puseram para ele à parte, e separadamente para eles, e à parte para os egípcios que com ele comiam: porque os egípcios não podem comer pão com os hebreus, o qual é abominação aos egípcios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 33, 'E sentaram-se diante dele, o mais velho conforme sua primogenitura, e o mais novo conforme sua idade menor; e estavam aqueles homens atônitos olhando-se um ao outro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 43, 34, 'E ele tomou iguarias de diante de si para eles; mas a porção de Benjamim era cinco vezes como qualquer uma das deles. E beberam, e alegraram-se com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 1, 'E mandou José ao mordomo de sua casa, dizendo: Enche os sacos destes homens de alimentos, quanto puderem levar, e põe o dinheiro de cada um na boca de seu saco:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 2, 'E porás meu copo, o copo de prata, na boca do saco do mais novo, com o dinheiro de seu trigo. E ele fez como disse José.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 3, 'Vinda a manhã, os homens foram despedidos com seus asnos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 4, 'Havendo eles saído da cidade, da qual ainda não haviam se afastado, disse José a seu mordomo: Levanta-te, e segue a esses homens; e quando os alcançares, dize-lhes: Por que retribuístes com o mal pelo bem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 5, 'Não é isto no que bebe meu senhor, e pelo que costuma adivinhar? Fizestes mal no que fizestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 6, 'E quando ele os alcançou, disse-lhes estas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 7, 'E eles lhe responderam: Por que diz meu senhor tais coisas? Nunca tal façam teus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 8, 'Eis que, o dinheiro que achamos na boca de nossos sacos, o voltamos a trazer a ti desde a terra de Canaã; como, pois, havíamos de furtar da casa de teu senhor prata nem ouro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 9, 'Aquele de teus servos em quem for achado o copo, que morra, e ainda nós seremos servos de meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 10, 'E ele disse: Também agora seja conforme vossas palavras; aquele em quem se achar, será meu servo, e vós sereis sem culpa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 11, 'Eles então se deram pressa, e derrubando cada um seu saco em terra, abriu cada qual o seu saco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 12, 'E buscou; desde o mais velho começou, e acabou no mais novo; e o copo foi achado no saco de Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 13, 'Então eles rasgaram suas roupas, e carregou cada um seu asno, e voltaram à cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 14, 'E chegou Judá com seus irmãos à casa de José, que ainda estava ali, e prostraram-se diante dele em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 15, 'E disse-lhes José: Que obra é esta que fizestes? Não sabeis que um homem como eu sabe adivinhar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 16, 'Então disse Judá: Que diremos a meu senhor? Que falaremos? Ou com que nos justificaremos? Deus achou a maldade de teus servos: eis que, nós somos servos de meu senhor, nós, e também aquele em cujo poder foi achado o copo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 17, 'E ele respondeu: Nunca eu tal faça: o homem em cujo poder foi achado o copo, ele será meu servo; vós ide em paz a vosso pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 18, 'Então Judá se chegou a ele, e disse: Ai senhor meu, rogo-te que fale teu servo uma palavra aos ouvidos de meu senhor, e não se acenda tua ira contra teu servo, pois que tu és como Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 19, 'Meu senhor perguntou a seus servos, dizendo: Tendes pai ou irmão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 20, 'E nós respondemos a meu senhor: Temos um pai ancião, e um jovem que lhe nasceu em sua velhice, pequeno ainda; e um irmão seu morreu, e ele restou sozinho de sua mãe, e seu pai o ama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 21, 'E tu disseste a teus servos: Trazei-o a mim, e porei meus olhos sobre ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 22, 'E nós dissemos a meu senhor: O jovem não pode deixar a seu pai, porque se o deixar, seu pai morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 23, 'E disseste a teus servos: Se vosso irmão mais novo não descer convosco, não vejais mais meu rosto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 24, 'Aconteceu, pois, que quando chegamos a meu pai teu servo, nós lhe contamos as palavras de meu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 25, 'E disse nosso pai: Voltai a comprar-nos um pouco de alimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 26, 'E nós respondemos: Não podemos ir: se nosso irmão for conosco, iremos; porque não podemos ver o rosto do homem, não estando conosco nosso irmão o mais novo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 27, 'Então teu servo meu pai nos disse: Vós sabeis que dois me deu minha mulher;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 28, 'E um saiu de minha presença, e penso certamente que foi despedaçado, e até agora não o vi;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 29, 'E se tomardes também este de diante de mim, e lhe acontecer algum desastre, fareis descer meus cabelos grisalhos com tristeza ao Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 30, 'Agora, pois, quando chegar eu a teu servo meu pai, e o jovem não for comigo, como sua alma está ligada à alma dele,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 31, 'Sucederá que quando perceber a ausência do jovem, morrerá; e teus servos farão descer os cabelos grisalhos de teu servo, nosso pai, com tristeza ao Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 32, 'Como teu servo saiu por fiador do jovem com meu pai, dizendo: Se eu não o devolver a ti, então eu serei culpável para meu pai todos os dias;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 33, 'Rogo-te, portanto, que fique agora teu servo pelo jovem por servo de meu senhor, e que o jovem vá com seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 44, 34, 'Porque como irei eu a meu pai sem o jovem? Não poderei, por não ver o mal que sobrevirá a meu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 1, 'Não podia já José se conter diante de todos os que estavam ao seu lado, e clamou: Fazei sair de minha presença a todos. E não ficou ninguém com ele, ao dar-se a conhecer José a seus irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 2, 'Então se deu a chorar por voz em grito; e ouviram os egípcios, e ouviu também a casa de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 3, 'E disse José a seus irmãos: Eu sou José: vive ainda meu pai? E seus irmãos não puderam lhe responder, porque estavam perturbados diante dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 4, 'Então disse José a seus irmãos: Achegai-vos agora a mim. E eles se achegaram. E ele disse: Eu sou José vosso irmão o que vendestes para o Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 5, 'Agora, pois, não vos entristeçais, nem vos pese de haver me vendido aqui; que para preservação de vida me enviou Deus diante de vós:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 6, 'Que já houve dois anos de fome em meio da terra, e ainda restam cinco anos em que nem haverá arada nem colheita.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 7, 'E Deus me enviou adiante de vós, para que vós restásseis na terra, e para vos dar vida por meio de grande salvamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 8, 'Assim, pois, não me enviastes vós aqui, mas sim Deus, que me pôs por pai de Faraó, e por senhor de toda sua casa, e por governador de toda a terra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 9, 'Apressai-vos, ide a meu pai e dizei-lhe: Assim diz teu filho José: Deus me pôs por senhor de todo Egito; vem a mim, não te detenhas:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 10, 'E habitarás na terra de Gósen, e estarás perto de mim, tu e teus filhos, e os filhos de teus filhos, teus gados e tuas vacas, e tudo o que tens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 11, 'E ali te alimentarei, pois ainda restam cinco anos de fome, para que não pereças de pobreza tu e tua casa, e tudo o que tens:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 12, 'E eis que, vossos olhos veem, e os olhos de meu irmão Benjamim, que meu boca vos fala.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 13, 'Fareis pois saber a meu pai toda minha glória no Egito, e tudo o que vistes: e apressai-vos, e trazei a meu pai aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 14, 'E lançou-se sobre o pescoço de Benjamim seu irmão, e chorou; e também Benjamim chorou sobre seu pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 15, 'E beijou a todos os seus irmãos, e chorou sobre eles: e depois seus irmãos falaram com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 16, 'E ouviu-se a notícia na casa de Faraó, dizendo: Os irmãos de José vieram. E pareceu bem aos olhos de Faraó e de seus servos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 17, 'E disse Faraó a José: Dize a teus irmãos: Fazei isto: carregai vossos animais, e ide, voltai à terra de Canaã;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 18, 'E tomai a vosso pai e vossas famílias, e vinde a mim, que eu vos darei o bom da terra do Egito e comereis a gordura da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 19, 'E tu manda: Fazei isto: tomai para vós da terra do Egito carros para vossos filhos e vossas mulheres; e tomai a vosso pai, e vinde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 20, 'E não se vos dê nada de vossos pertences, porque o bem da terra do Egito será vosso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 21, 'E fizeram-no assim os filhos de Israel: e deu-lhes José carros conforme a ordem de Faraó, e deu alimentos para o caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 22, 'A cada um de todos eles deu mudas de roupas, e a Benjamim deu trezentas peças de prata, e cinco mudas de roupas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 23, 'E a seu pai enviou isto: dez asnos carregados do melhor do Egito, e dez asnas carregadas de trigo, e pão e comida, para seu pai no caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 24, 'E despediu a seus irmãos, e foram-se. E ele lhes disse: Não brigais pelo caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 25, 'E subiram do Egito, e chegaram à terra de Canaã a Jacó seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 26, 'E deram-lhe as novas, dizendo: José vive ainda; e ele é senhor toda a terra do Egito. E seu coração se desmaiou; pois não cria neles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 27, 'E eles lhe contaram todas as palavras de José, que ele lhes havia falado; e vendo ele os carros que José enviava para levá-lo, o espírito de Jacó seu pai reviveu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 45, 28, 'Então disse Israel: Basta; José meu filho vive ainda: irei, e lhe verei antes que eu morra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 1, 'E partiu-se Israel com tudo o que tinha, e veio a Berseba, e ofereceu sacrifícios ao Deus de seu pai Isaque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 2, 'E falou Deus a Israel em visões de noite, e disse: Jacó, Jacó. E ele respondeu: Eis-me aqui.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 3, 'E disse: Eu sou Deus, o Deus de teu pai; não temas de descer ao Egito, porque eu te farei ali em grande nação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 4, 'Eu descerei contigo ao Egito, e eu também te farei voltar; e José porá sua mão sobre teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 5, 'E levantou-se Jacó de Berseba; e tomaram os filhos de Israel a seu pai Jacó, e a seus filhos, e a suas mulheres, nos carros que Faraó havia enviado para levá-lo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 6, 'E tomaram seus gados, e sua riqueza que havia adquirido na terra de Canaã, e vieram-se ao Egito, Jacó, e toda sua descendência consigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 7, 'Seus filhos, e os filhos de seus filhos consigo; suas filhas, e as filhas de seus filhos, e a toda sua descendência trouxe consigo ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 8, 'E estes são os nomes dos filhos de Israel, que entraram no Egito, Jacó e seus filhos: Rúben, o primogênito de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 9, 'E os filhos de Rúben: Enoque, e Palu, e Hezrom, e Carmi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 10, 'E os filhos de Simeão: Jemuel, e Jamim, e Oade, e Jaquim, e Zoar, e Saul, filho da cananeia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 11, 'E os filhos de Levi: Gérson, Coate, e Merari.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 12, 'E os filhos de Judá: Er, e Onã, e Selá, e Perez, e Zerá: mas Er e Onã, morreram na terra de Canaã. E os filhos de Perez foram Hezrom e Hamul.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 13, 'E os filhos de Issacar: Tola, e Puva, e Jó, e Sinrom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 14, 'E os filhos de Zebulom: Serede e Elom, e Jaleel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 15, 'Estes foram os filhos de Lia, os que deu a Jacó em Padã-Arã, e além de sua filha Diná: trinta e três as almas todas de seus filhos e filhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 16, 'E os filhos de Gade: Zifiom, e Hagi, e Suni, e Ezbom, e Eri, e Arodi, e Areli.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 17, 'E os filhos de Aser: Imna, e Isva, e Isvi y Berias, e Sera, irmã deles. Os filhos de Berias: Héber, e Malquiel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 18, 'Estes foram os filhos de Zilpa, a que Labão deu a sua filha Lia, e deu estes a Jacó; todas dezesseis almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 19, 'E os filhos de Raquel, mulher de Jacó: José e Benjamim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 20, 'E nasceram a José na terra do Egito Manassés e Efraim, os que lhe deu Azenate, filha Potífera, sacerdote de Om.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 21, 'E os filhos de Benjamim foram Belá, e Bequer e Asbel, e Gera, e Naamã, e Eí, e Rôs e Mupim, e Hupim, e Arde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 22, 'Estes foram os filhos de Raquel, que nasceram a Jacó: ao todo, catorze almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 23, 'E os filhos de Dã: Husim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 24, 'E os filhos de Naftali: Jazeel, e Guni, e Jezer, e Silém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 25, 'Estes foram os filhos de Bila, a que deu Labão a Raquel sua filha, e ela deu à luz estes a Jacó; todas sete almas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 26, 'Todas as pessoas que vieram com Jacó ao Egito, procedentes de seus lombos, sem as mulheres dos filhos de Jacó, todas as pessoas foram sessenta e seis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 27, 'E os filhos de José, que lhe nasceram no Egito, duas pessoas. Todas as almas da casa de Jacó, que entraram no Egito, foram setenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 28, 'E enviou a Judá adiante de si a José, para que lhe viesse a ver a Gósen; e chegaram à terra de Gósen.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 29, 'E José preparou seu carro e veio a receber a Israel seu pai a Gósen; e se manifestou a ele, e lançou-se sobre seu pescoço, e chorou sobre seu pescoço bastante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 30, 'Então Israel disse a José: Morra eu agora, já que vi teu rosto, pois ainda vives.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 31, 'E José disse a seus irmãos, e à casa de seu pai: Subirei e farei saber a Faraó, e lhe direi: Meus irmãos e a casa de meu pai, que estavam na terra de Canaã, vieram a mim;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 32, 'E os homens são pastores de ovelhas, porque são homens criadores de gado: e trouxeram suas ovelhas e suas vacas, e tudo o que tinham.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 33, 'E quando Faraó vos chamar e disser: qual é vosso ofício?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 46, 34, 'Então direis: Homens de criação de gado foram teus servos desde nossa juventude até agora, nós e nossos pais; a fim que moreis na terra de Gósen, porque os egípcios abominam todo pastor de ovelhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 1, 'E José veio, e fez saber a Faraó, e disse: Meu pai e meus irmãos, e suas ovelhas e suas vacas, com tudo o que têm, vieram da terra de Canaã, e eis que, estão na terra de Gósen.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 2, 'E dentre seus irmãos tomou cinco homens, e os apresentou diante de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 3, 'E Faraó disse a seus irmãos: Qual é vosso ofício? E eles responderam a Faraó: Pastores de ovelhas são teus servos, tanto nós como nossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 4, 'Disseram ademais a Faraó: Por morar nesta terra viemos; porque não há pasto para as ovelhas de teus servos, pois a fome é grave na terra de Canaã: portanto, te rogamos agora que habitem teus servos na terra de Gósen.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 5, 'Então Faraó falou a José, dizendo: Teu pai e teus irmãos vieram a ti;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 6, 'A terra do Egito diante de ti está; no melhor da terra faze habitar a teu pai e a teus irmãos; habitem na terra de Gósen; e se entendes que há entre eles homens competentes, põe-os por administradores do meu gado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 7, 'E José introduziu a seu pai, e apresentou-o diante de Faraó; e Jacó abençoou a Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 8, 'E disse Faraó a Jacó: Quantos são os dias dos anos de tua vida?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 9, 'E Jacó respondeu a Faraó: Os dias dos anos de minha peregrinação são cento e trinta anos; poucos e maus foram os dias dos anos de minha vida, e não chegaram aos dias dos anos da vida de meus pais nos dias de sua peregrinação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 10, 'E Jacó abençoou a Faraó, e saiu-se de diante de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 11, 'Assim José fez habitar a seu pai e a seus irmãos, e deu-lhes possessão na terra do Egito, no melhor da terra, na terra de Ramessés como mandou Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 12, 'E alimentava José a seu pai e a seus irmãos, e a toda a casa de seu pai, de pão, segundo o número de seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 13, 'E não havia pão toda a terra, e a fome era muito grave; pelo que desfaleceu de fome a terra do Egito e a terra de Canaã.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 14, 'E recolheu José todo o dinheiro que se achou na terra do Egito e na terra de Canaã, pelos alimentos que dele compravam; e meteu José o dinheiro na casa de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 15, 'E acabado o dinheiro da terra do Egito e da terra de Canaã, veio todo Egito a José dizendo: Dá-nos pão: por que morreremos diante de ti, por haver-se acabado o dinheiro?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 16, 'E José disse: Dai vossos gados, e eu vos darei por vossos gados, se se acabou o dinheiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 17, 'E eles trouxeram seus gados a José; e José lhes deu alimentos por cavalos, e pelo rebanho das ovelhas, e pelo rebanho das vacas, e por asnos: e sustentou-os de pão por todos os seus gados aquele ano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 18, 'E acabado aquele ano, vieram a ele o segundo ano, e lhe disseram: Não encobriremos a nosso senhor que o dinheiro certamente se acabou; também o gado é já de nosso senhor; nada restou diante de nosso senhor a não ser nossos corpos e nossa terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 19, 'Por que morreremos diante de teus olhos, tanto nós como nossa terra? Compra a nós e a nossa terra por pão, e seremos nós e nossa terra servos de Faraó; e dá-nos semente para que vivamos e não morramos, e não seja assolada a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 20, 'Então comprou José toda a terra do Egito para Faraó; pois os egípcios venderam cada um suas terras, porque se agravou a fome sobre eles: e a terra veio a ser de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 21, 'E ao povo o fez passar às cidades desde um fim do termo do Egito até o outro fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 22, 'Somente a terra dos sacerdotes não comprou, porquanto os sacerdotes tinham ração de Faraó, e eles comiam sua ração que Faraó lhes dava: por isso não venderam sua terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 23, 'E José disse ao povo: Eis que comprei hoje vós e vossa terra para Faraó: vede aqui semente, e semeareis a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 24, 'E será que dos frutos dareis o quinto a Faraó, e as quatro partes serão vossas para semear as terras, e para vosso mantimento, e dos que estão em vossas casas, e para que comam vossos meninos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 25, 'E eles responderam: A vida nos deste: achemos favor aos olhos de meu senhor, e sejamos servos de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 26, 'Então José o pôs por estatuto até hoje sobre a terra do Egito, assinalando para Faraó o quinto; exceto somente a terra dos sacerdotes, que não foi de Faraó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 27, 'Assim habitou Israel na terra do Egito, na terra de Gósen; e apossaram-se nela, y se aumentaram, e multiplicaram em grande maneira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 28, 'E viveu Jacó na terra do Egito dezessete anos: e foram os dias de Jacó, os anos de sua vida, cento quarenta e sete anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 29, 'E achegaram-se os dias de Israel para morrer, e chamou a José seu filho, e lhe disse: Se achei agora favor em teus olhos, rogo-te que ponhas tua mão debaixo de minha coxa, e farás comigo misericórdia e verdade; rogo-te que não me enterres no Egito;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 30, 'Mas quando dormir com meus pais, me levarás de Egito, e me sepultarás no sepulcro deles. E ele respondeu: Eu farei como tu dizes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 47, 31, 'E ele disse: Jura-me isso. E ele lhe jurou. Então Israel se inclinou sobre a cabeceira da cama.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 1, 'E sucedeu depois destas coisas que foi dito a José: Eis que teu pai está enfermo. E ele tomou consigo seus dois filhos Manassés e Efraim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 2, 'E se fez saber a Jacó, dizendo: Eis que teu filho José vem a ti. Então se esforçou Israel, e sentou-se sobre a cama;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 3, 'E disse a José: O Deus Todo-Poderoso me apareceu em Luz na terra de Canaã, e me abençoou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 4, 'E disse-me: Eis que, eu te farei crescer, e te multiplicarei, e te porei por conjunto de povos: e darei esta terra à tua descendência depois de ti por herança perpétua.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 5, 'E agora teus dois filhos Efraim e Manassés, que te nasceram na terra do Egito, antes que viesse a ti à terra do Egito, meus são; como Rúben e Simeão, serão meus:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 6, 'E os que depois deles geraste, serão teus; pelo nome de seus irmãos serão chamados em suas propriedades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 7, 'Porque quando eu vinha de Padã-Arã, se me morreu Raquel na terra de Canaã, no caminho, como certa distância vindo a Efrata; e sepultei-a ali no caminho de Efrata, que é Belém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 8, 'E viu Israel os filhos de José, e disse: Quem são estes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 9, 'E respondeu José a seu pai: São meus filhos, que Deus me deu aqui. E ele disse: Achegai-os agora a mim, e os abençoarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 10, 'E os olhos de Israel estavam tão agravados da velhice, que não podia ver. Fez-lhes, pois, chegar a ele, e ele os beijou e abraçou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 11, 'E disse Israel a José: Não pensava eu ver teu rosto, e eis que Deus me fez ver também tua descendência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 12, 'Então José os tirou dentre seus joelhos, e inclinou-se à terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 13, 'E tomou-os José a ambos, Efraim à sua direita, à esquerda de Israel; e a Manassés à sua esquerda, à direita de Israel; e fez-lhes chegar a ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 14, 'Então Israel estendeu sua mão direita, e a pôs sobre a cabeça de Efraim, que era o mais novo, e sua esquerda sobre a cabeça de Manassés, colocando assim suas mãos propositadamente, ainda que Manassés era o primogênito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 15, 'E abençoou a José, e disse: O Deus em cuja presença andaram meus pais Abraão e Isaque, o Deus que me mantém desde que eu sou até hoje,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 16, 'O Anjo que me liberta de todo mal abençoe a estes moços: e meu nome seja chamado neles, e o nome de meus pais Abraão e Isaque: e multipliquem em grande maneira em meio da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 17, 'Então vendo José que seu pai punha a direita sobre a cabeça de Efraim, causou-lhe isto desgosto; e pegou a mão de seu pai, para mudá-la de sobre a cabeça de Efraim à cabeça de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 18, 'E disse José a seu pai: Não assim, meu pai, porque este é o primogênito; põe tua mão direita sobre sua cabeça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 19, 'Mas seu pai não quis, e disse: Eu sei, meu filho, eu sei: também ele virá a ser um povo, e será também acrescentado; porém seu irmão mais novo será maior que ele, e sua descendência será plenitude de povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 20, 'E abençoou-os aquele dia, dizendo: Em ti Israel abençoará, dizendo: Deus faça de ti Deus como a Efraim e como a Manassés. E pôs a Efraim diante de Manassés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 21, 'E disse Israel a José: Eis que eu morro, mas Deus será convosco, e vos fará voltar à terra de vossos pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 48, 22, 'E eu dei a ti uma parte sobre teus irmãos, a qual tomei eu da mão dos amorreus com minha espada e com meu arco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 1, 'E chamou Jacó a seus filhos, e disse: Juntai-vos, e vos declararei o que vos há de acontecer nos últimos dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 2, 'Juntai-vos e ouvi, filhos de Jacó; E escutai a vosso pai Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 3, 'Rúben, tu és meu primogênito, minha força, e o princípio do meu vigor; Principal em dignidade, principal em poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 4, 'Corrente como as águas, não sejas o principal; Porquanto subiste ao leito de teu pai: Então te contaminaste, subindo a meu estrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 5, 'Simeão e Levi, irmãos: Armas de violência são suas armas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 6, 'Em seu secreto não entre minha alma, nem minha honra se junte em sua companhia; Que em seu furor mataram homem, E em sua vontade aleijaram bois.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 7, 'Maldito seu furor, que foi bravio; E sua ira, que foi dura: Eu os dividirei em Jacó, E os espalharei em Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 8, 'Judá, teus irmãos te louvarão: Tua mão esterá sobre o pescoço de teus inimigos: Os filhos de teu pai se inclinarão a ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 9, 'Jovem leão é Judá: Da presa subiste, filho meu: Encurvou-se, lançou-se como leão, Assim como leão velho; quem o despertará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 10, 'Não será tirado o cetro de Judá, E o legislador dentre seus pés, Até que venha Siló; E a ele se congregarão os povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 11, 'Atando à vide seu jumentinho, E à videira o filho de sua jumenta, Lavou no veio sua roupa, E no sangue de uvas seu manto:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 12, 'Seus olhos mais vermelhos que o vinho, E os dentes mais brancos que o leite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 13, 'Zebulom em portos de mar habitará, E será para porto de navios; E seu termo até Sidom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 14, 'Issacar, asno de forte estrutura deitado entre dois apriscos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 15, 'E viu que o descanso era bom, E que a terra era deleitosa; E baixou seu ombro para levar, E serviu em tributo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 16, 'Dã julgará a seu povo, Como uma das tribos de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 17, 'Será Dã serpente junto ao caminho, víbora junto à vereda, que morde os calcanhares dos cavalos, e faz cair por detrás ao cavaleiro deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 18, 'Tua salvação espero, ó SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 19, 'Gade, exército o atacará; mas ele contra-atacará ao fim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 20, 'O pão de Aser será espesso, E ele dará deleites ao rei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 21, 'Naftali, serva solta, que diz belas coisas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 22, 'Ramo frutífero é José, ramo frutífero é junto à fonte, cujos ramos se estendem sobre o muro;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 23, 'E causaram-lhe amargura, e flecharam-lhe, e os arqueiros o odiaram;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 24, 'Mas seu arco manteve-se forte, E os braços de suas mãos se fortaleceram pelas mãos do Forte de Jacó, (Dali é o Pastor, e a Pedra de Israel,)'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 25, 'Do Deus de teu pai, o qual te ajudará, E do Todo-Poderoso, o qual te abençoará com bênçãos dos céus de acima, com bênçãos do abismo que está abaixo, Com bênçãos do seio e da madre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 1, 'Gênesis', 'Gn', 49, 26, 'As bênçãos de teu pai Foram maiores que as bênçãos de meus progenitores: Até o termo das colinas eternas serão sobre a cabeça de José, E sobre o topo da cabeça do que foi separado de seus irmãos.')
